// Method: GraphEdit::get_connection_line
static JSValue js_GraphEdit_get_connection_line(JSContext* ctx, JSValueConst this_val, int argc, JSValueConst* argv) {
    if (argc < 1) {
        return JS_ThrowTypeError(ctx, "GraphEdit.get_connection_line: missing handle argument");
    }

    int64_t handle;
    if (JS_ToInt64(ctx, &handle, argv[0]) < 0) {
        return JS_ThrowTypeError(ctx, "GraphEdit.get_connection_line: invalid handle");
    }

    QuickJSContext* qjs_ctx = get_qjs_ctx(ctx);
    if (!qjs_ctx || !qjs_ctx->get_object_registry()) {
        return JS_ThrowInternalError(ctx, "Context not initialized");
    }

    Object* obj = qjs_ctx->get_object_registry()->get_object(handle);
    if (!obj) {
        return JS_ThrowTypeError(ctx, "GraphEdit.get_connection_line: invalid or freed object");
    }

    GraphEdit* typed_obj = Object::cast_to<GraphEdit>(obj);
    if (!typed_obj) {
        return JS_ThrowTypeError(ctx, "GraphEdit.get_connection_line: object is not a GraphEdit");
    }

    // Argument count check (excluding handle) - only required args
    if (argc < 3) {
        return JS_ThrowTypeError(ctx, "GraphEdit.get_connection_line: expected at least 2 arguments, got %d", argc - 1);
    }

    // Convert arguments
    double tmp_x_from_node, tmp_y_from_node;
    JSValue jx_from_node = JS_GetPropertyStr(ctx, argv[1], "x");
    JSValue jy_from_node = JS_GetPropertyStr(ctx, argv[1], "y");
    JS_ToFloat64(ctx, &tmp_x_from_node, jx_from_node);
    JS_ToFloat64(ctx, &tmp_y_from_node, jy_from_node);
    JS_FreeValue(ctx, jx_from_node);
    JS_FreeValue(ctx, jy_from_node);
    Vector2 arg_from_node(tmp_x_from_node, tmp_y_from_node);
    double tmp_x_to_node, tmp_y_to_node;
    JSValue jx_to_node = JS_GetPropertyStr(ctx, argv[2], "x");
    JSValue jy_to_node = JS_GetPropertyStr(ctx, argv[2], "y");
    JS_ToFloat64(ctx, &tmp_x_to_node, jx_to_node);
    JS_ToFloat64(ctx, &tmp_y_to_node, jy_to_node);
    JS_FreeValue(ctx, jx_to_node);
    JS_FreeValue(ctx, jy_to_node);
    Vector2 arg_to_node(tmp_x_to_node, tmp_y_to_node);

    PackedVector2Array result = typed_obj->get_connection_line(arg_from_node, arg_to_node);
    JSValue arr = JS_NewArray(ctx);
    for (int i = 0; i < result.size(); i++) {
        JSValue vec = JS_NewObject(ctx);
        JS_SetPropertyStr(ctx, vec, "x", JS_NewFloat64(ctx, result[i].x));
        JS_SetPropertyStr(ctx, vec, "y", JS_NewFloat64(ctx, result[i].y));
        JS_SetPropertyUint32(ctx, arr, i, vec);
    }
    return arr;
}

